"""サーバー全体を javac で確かめるための「形だけのライブラリ」を作る（Spring・JPA・サーブレットなど、この環境では落とせないもの）。
python3 tools/javacheck/make_libstubs.py <出力先>  → <出力先> の下に .java を書く。中身は空の形だけ。"""
import os, sys
OUT = sys.argv[1]
def w(path, src):
    p = os.path.join(OUT, path.replace('.', '/') + '.java')
    os.makedirs(os.path.dirname(p), exist_ok=True)
    pkg, name = path.rsplit('.', 1)
    open(p, 'w').write(f'package {pkg};\n{src}\n')
A = lambda name, body='': f'import java.lang.annotation.*; @Retention(RetentionPolicy.RUNTIME) public @interface {name} {{ {body} }}'
# jakarta
w('jakarta.annotation.PostConstruct', A('PostConstruct'))
w('jakarta.annotation.PreDestroy', A('PreDestroy'))
w('jakarta.persistence.Entity', A('Entity'))
w('jakarta.persistence.Id', A('Id'))
w('jakarta.persistence.Table', A('Table', 'String name() default "";'))
w('jakarta.persistence.Column', A('Column', 'String name() default ""; boolean nullable() default true; boolean unique() default false; int length() default 255;'))
w('jakarta.persistence.GenerationType', 'public enum GenerationType { IDENTITY, AUTO, SEQUENCE }')
w('jakarta.persistence.GeneratedValue', A('GeneratedValue', 'GenerationType strategy() default GenerationType.AUTO;'))
w('jakarta.persistence.EnumType', 'public enum EnumType { STRING, ORDINAL }')
w('jakarta.persistence.Enumerated', A('Enumerated', 'EnumType value() default EnumType.ORDINAL;'))
w('jakarta.persistence.FetchType', 'public enum FetchType { LAZY, EAGER }')
w('jakarta.persistence.ManyToOne', A('ManyToOne', 'FetchType fetch() default FetchType.EAGER; boolean optional() default true;'))
w('jakarta.persistence.JoinColumn', A('JoinColumn', 'String name() default ""; boolean nullable() default true;'))
w('jakarta.servlet.http.HttpSession', 'public interface HttpSession { Object getAttribute(String k); void setAttribute(String k, Object v); }')
w('jakarta.servlet.http.HttpServletRequest', 'public interface HttpServletRequest { String getParameter(String k); HttpSession getSession(boolean c); String getHeader(String k); String getRemoteAddr(); void setAttribute(String k, Object v); String getContextPath(); }')
w('jakarta.servlet.http.HttpServletResponse', 'public interface HttpServletResponse { void sendRedirect(String s) throws java.io.IOException; void setStatus(int s); }')
w('jakarta.validation.Valid', A('Valid'))
w('jakarta.validation.constraints.NotBlank', A('NotBlank'))
w('jakarta.validation.constraints.PositiveOrZero', A('PositiveOrZero'))
w('jakarta.validation.constraints.Size', A('Size', 'int max() default Integer.MAX_VALUE; int min() default 0;'))
w('jakarta.validation.constraints.Pattern', A('Pattern', 'String regexp();'))
# spring 注釈
S = 'org.springframework.'
for n in ['stereotype.Service', 'stereotype.Controller', 'stereotype.Component']:
    w(S + n, A(n.rsplit('.', 1)[1], 'String value() default "";'))
w(S + 'context.annotation.Configuration', A('Configuration'))
w(S + 'context.annotation.Bean', A('Bean'))
w(S + 'beans.factory.annotation.Value', A('Value', 'String value();'))
w(S + 'scheduling.annotation.Scheduled', A('Scheduled', 'long fixedDelay() default -1; long fixedRate() default -1; long initialDelay() default -1;'))
w(S + 'scheduling.annotation.EnableScheduling', A('EnableScheduling'))
w(S + 'transaction.annotation.Transactional', A('Transactional', 'boolean readOnly() default false;'))
w(S + 'transaction.event.TransactionalEventListener', A('TransactionalEventListener'))
for n in ['GetMapping', 'PostMapping', 'PutMapping', 'DeleteMapping', 'RequestMapping']:
    w(S + 'web.bind.annotation.' + n, A(n, 'String[] value() default {};'))
w(S + 'web.bind.annotation.RequestParam', A('RequestParam', 'String value() default ""; boolean required() default true; String defaultValue() default "";'))
w(S + 'web.bind.annotation.RequestHeader', A('RequestHeader', 'String value() default ""; boolean required() default true;'))
w(S + 'web.bind.annotation.PathVariable', A('PathVariable', 'String value() default "";'))
w(S + 'web.bind.annotation.RequestBody', A('RequestBody'))
w(S + 'web.bind.annotation.RestController', A('RestController'))
w(S + 'web.bind.annotation.ResponseStatus', A('ResponseStatus', 'org.springframework.http.HttpStatus value();'))
w(S + 'web.bind.annotation.ControllerAdvice', A('ControllerAdvice', 'String[] basePackages() default {}; Class<?>[] assignableTypes() default {};'))
w(S + 'web.bind.annotation.ModelAttribute', A('ModelAttribute', 'String value() default "";'))
w(S + 'boot.context.properties.ConfigurationProperties', A('ConfigurationProperties', 'String value() default ""; String prefix() default "";'))
# spring クラス
w(S + 'beans.factory.ObjectProvider', 'public interface ObjectProvider<T> { T getIfAvailable(); default java.util.stream.Stream<T> orderedStream() { return java.util.stream.Stream.empty(); } }')
w(S + 'context.ApplicationEventPublisher', 'public interface ApplicationEventPublisher { void publishEvent(Object e); }')
w(S + 'core.io.ClassPathResource', 'public class ClassPathResource { public ClassPathResource(String p) {} public java.io.InputStream getInputStream() throws java.io.IOException { return null; } }')
w(S + 'dao.DuplicateKeyException', 'public class DuplicateKeyException extends RuntimeException { public DuplicateKeyException(String m) { super(m); } }')
w(S + 'data.jpa.repository.JpaRepository', 'public interface JpaRepository<T, ID> { <S extends T> S save(S e); java.util.Optional<T> findById(ID id); java.util.List<T> findAll(); void delete(T e); long count(); }')
w(S + 'http.HttpStatus', 'public enum HttpStatus { OK, CREATED, NO_CONTENT, BAD_REQUEST, UNAUTHORIZED, FORBIDDEN, NOT_FOUND, CONFLICT, GONE, TOO_MANY_REQUESTS, PAYLOAD_TOO_LARGE, INTERNAL_SERVER_ERROR }')
w(S + 'http.ResponseEntity', 'public class ResponseEntity<T> { public interface HeadersBuilder { <X> ResponseEntity<X> build(); <X> ResponseEntity<X> body(X b); } public static <T> ResponseEntity<T> ok(T b) { return null; } public static HeadersBuilder noContent() { return null; } public static HeadersBuilder status(org.springframework.http.HttpStatus s) { return null; } }')
w(S + 'jdbc.core.RowCallbackHandler', 'public interface RowCallbackHandler { void processRow(java.sql.ResultSet rs) throws java.sql.SQLException; }')
w(S + 'jdbc.core.RowMapper', 'public interface RowMapper<T> { T mapRow(java.sql.ResultSet rs, int i) throws java.sql.SQLException; }')
w(S + 'jdbc.core.JdbcTemplate', 'public class JdbcTemplate { public void query(String sql, RowCallbackHandler h, Object... args) {} public <T> java.util.List<T> query(String sql, RowMapper<T> m, Object... args) { return null; } public <T> java.util.List<T> queryForList(String sql, Class<T> t, Object... args) { return null; } public <T> T queryForObject(String sql, Class<T> t, Object... args) { return null; } public int update(String sql, Object... args) { return 0; } }')
w(S + 'security.crypto.password.PasswordEncoder', 'public interface PasswordEncoder { String encode(CharSequence s); boolean matches(CharSequence a, String b); }')
w(S + 'ui.Model', 'public interface Model { Model addAttribute(String k, Object v); }')
w(S + 'web.servlet.mvc.support.RedirectAttributes', 'public interface RedirectAttributes { RedirectAttributes addFlashAttribute(String k, Object v); }')
w(S + 'web.server.ResponseStatusException', 'public class ResponseStatusException extends RuntimeException { public ResponseStatusException(org.springframework.http.HttpStatus s) { super(""); } public ResponseStatusException(org.springframework.http.HttpStatus s, String r) { super(r); } public String getReason() { return getMessage(); } }')
w(S + 'web.servlet.HandlerInterceptor', 'public interface HandlerInterceptor { default boolean preHandle(jakarta.servlet.http.HttpServletRequest a, jakarta.servlet.http.HttpServletResponse b, Object h) throws Exception { return true; } default void afterCompletion(jakarta.servlet.http.HttpServletRequest a, jakarta.servlet.http.HttpServletResponse b, Object h, Exception e) throws Exception {} }')
w(S + 'web.servlet.config.annotation.InterceptorRegistration', 'public interface InterceptorRegistration { InterceptorRegistration addPathPatterns(String... p); InterceptorRegistration excludePathPatterns(String... p); }')
