w(S + 'web.socket.CloseStatus', 'public class CloseStatus { public static final CloseStatus NORMAL = new CloseStatus(), POLICY_VIOLATION = new CloseStatus(); }')
w(S + 'web.socket.TextMessage', 'public class TextMessage { public TextMessage(CharSequence s) {} public String getPayload() { return ""; } public int getPayloadLength() { return 0; } }')
w(S + 'web.socket.WebSocketSession', 'public interface WebSocketSession { String getId(); boolean isOpen(); void sendMessage(TextMessage m) throws java.io.IOException; void close() throws java.io.IOException; void close(CloseStatus s) throws java.io.IOException; }')
w(S + 'web.socket.handler.ConcurrentWebSocketSessionDecorator', 'public class ConcurrentWebSocketSessionDecorator implements org.springframework.web.socket.WebSocketSession { public ConcurrentWebSocketSessionDecorator(org.springframework.web.socket.WebSocketSession s, int a, int b) {} public String getId() { return ""; } public boolean isOpen() { return true; } public void sendMessage(org.springframework.web.socket.TextMessage m) {} public void close() {} public void close(org.springframework.web.socket.CloseStatus s) {} }')
w(S + 'web.socket.handler.TextWebSocketHandler', 'public class TextWebSocketHandler { public void afterConnectionEstablished(org.springframework.web.socket.WebSocketSession s) throws Exception {} protected void handleTextMessage(org.springframework.web.socket.WebSocketSession s, org.springframework.web.socket.TextMessage m) throws Exception {} public void afterConnectionClosed(org.springframework.web.socket.WebSocketSession s, org.springframework.web.socket.CloseStatus c) throws Exception {} }')
print('ok')
